// Core tests: the 11 literal core cases from fixtures.json (expected
// values taken verbatim from the fixed spec candidate's file, never
// generated by the product), plus boundary and validation cases whose
// expected values were derived by hand from the SPEC's rules and
// cross-checked with an independent exact-fraction calculation.

import assert from "node:assert/strict";
import test from "node:test";
import { formatKg, run } from "../public/js/core/one-rep-max.mjs";
import fixtures from "./fixtures.json" with { type: "json" };

const coreCases = fixtures.cases.filter((entry) => entry.kind === "core");
for (const entry of coreCases) {
  test(`fixture ${entry.id}: ${entry.purpose}`, () => {
    assert.deepEqual(run(entry.input), entry.expected);
  });
}

function rowsFrom(base, loads) {
  const table = [
    [95, 2], [90, 4], [85, 6], [80, 8], [75, 10],
    [70, 12], [65, 16], [60, 20], [55, 24], [50, 30],
  ];
  return table.map(([percent, typicalReps], i) => ({
    percent,
    loadKg: loads[i],
    typicalReps,
  }));
}

test("upper endpoint: 1500 kg for 1 rep is its own 1RM with exact rows", () => {
  assert.deepEqual(run({ weight: "1500", reps: "1", unit: "kg" }), {
    ok: true,
    result: {
      epleyKg: 1500.0,
      brzyckiKg: 1500.0,
      oneRepMaxKg: 1500.0,
      highReps: false,
      rows: rowsFrom(1500, [1425.0, 1350.0, 1275.0, 1200.0, 1125.0, 1050.0, 975.0, 900.0, 825.0, 750.0]),
    },
  });
});

test("1500.00 with two decimals is still inside the range", () => {
  const outcome = run({ weight: "1500.00", reps: "1", unit: "kg" });
  assert.equal(outcome.ok, true);
  assert.equal(outcome.result.oneRepMaxKg, 1500.0);
});

test("1500.01 exceeds the range in the chosen unit", () => {
  assert.deepEqual(run({ weight: "1500.01", reps: "1", unit: "kg" }), {
    ok: false,
    error: { code: "RANGE", field: "weight", row: null },
  });
  assert.deepEqual(run({ weight: "1500.01", reps: "1", unit: "lb" }), {
    ok: false,
    error: { code: "RANGE", field: "weight", row: null },
  });
});

test("pounds at 1 rep: exact conversion, unrounded until the pinned points", () => {
  // 100 lb = 45.359237 kg exactly; estimates round to 45.4, the mean
  // rounds to the 0.5 step 45.5.
  assert.deepEqual(run({ weight: "100", reps: "1", unit: "lb" }), {
    ok: true,
    result: {
      epleyKg: 45.4,
      brzyckiKg: 45.4,
      oneRepMaxKg: 45.5,
      highReps: false,
      rows: rowsFrom(45.5, [43.0, 41.0, 38.5, 36.5, 34.0, 32.0, 29.5, 27.5, 25.0, 23.0]),
    },
  });
});

test("225 lb at 1 rep: wKg is 102.05828325 exactly, never pre-rounded", () => {
  const outcome = run({ weight: "225", reps: "1", unit: "lb" });
  assert.equal(outcome.ok, true);
  assert.equal(outcome.result.epleyKg, 102.1);
  assert.equal(outcome.result.brzyckiKg, 102.1);
  assert.equal(outcome.result.oneRepMaxKg, 102.0);
});

test("two reps with a fractional weight (60.25 kg)", () => {
  assert.deepEqual(run({ weight: "60.25", reps: "2", unit: "kg" }), {
    ok: true,
    result: {
      epleyKg: 64.3,
      brzyckiKg: 62.0,
      oneRepMaxKg: 63.0,
      highReps: false,
      rows: rowsFrom(63, [60.0, 56.5, 53.5, 50.5, 47.5, 44.0, 41.0, 38.0, 34.5, 31.5]),
    },
  });
});

test("smallest weight 0.01 kg at 1 rep follows the same rounding points", () => {
  const outcome = run({ weight: "0.01", reps: "1", unit: "kg" });
  assert.equal(outcome.ok, true);
  assert.equal(outcome.result.epleyKg, 0.0);
  assert.equal(outcome.result.oneRepMaxKg, 0.0);
});

test("empty fields: weight is reported before reps, reps before unit", () => {
  const empty = (field) => ({ ok: false, error: { code: "EMPTY", field, row: null } });
  assert.deepEqual(run({ weight: "", reps: "", unit: "" }), empty("weight"));
  assert.deepEqual(run({ weight: "100", reps: "", unit: "kg" }), empty("reps"));
  assert.deepEqual(run({ weight: "100", reps: "5", unit: "" }), empty("unit"));
});

test("input limit precedes format: 17 code units fail as INPUT_LIMIT", () => {
  const limit = (field) => ({ ok: false, error: { code: "INPUT_LIMIT", field, row: null } });
  assert.deepEqual(run({ weight: "12345678901234567", reps: "5", unit: "kg" }), limit("weight"));
  assert.deepEqual(run({ weight: "100", reps: "12345678901234567", unit: "kg" }), limit("reps"));
  assert.deepEqual(run({ weight: "100", reps: "5", unit: "kilograms-kilogra" }), limit("unit"));
});

test("a lone surrogate is UNICODE, checked before EMPTY and format", () => {
  assert.deepEqual(run({ weight: "1\uD800", reps: "5", unit: "kg" }), {
    ok: false,
    error: { code: "UNICODE", field: "weight", row: null },
  });
  assert.deepEqual(run({ weight: "100", reps: "\uDC00", unit: "kg" }), {
    ok: false,
    error: { code: "UNICODE", field: "reps", row: null },
  });
});

test("weight grammar: leading zeros, stray dots, spaces, full-width digits fail", () => {
  const format = { ok: false, error: { code: "DECIMAL_FORMAT", field: "weight", row: null } };
  for (const weight of ["007", "01", "1.234", "100.", ".5", " 100", "100 ", "１００", "1,000", "+100", "-5"]) {
    assert.deepEqual(run({ weight, reps: "5", unit: "kg" }), format, weight);
  }
});

test("reps grammar: decimals, signs, and leading zeros fail as INTEGER_FORMAT", () => {
  const format = { ok: false, error: { code: "INTEGER_FORMAT", field: "reps", row: null } };
  for (const reps of ["05", "5.0", "-5", "+5", " 5", "５"]) {
    assert.deepEqual(run({ weight: "100", reps, unit: "kg" }), format, reps);
  }
});

test("reps 0 is grammar-valid but out of range", () => {
  assert.deepEqual(run({ weight: "100", reps: "0", unit: "kg" }), {
    ok: false,
    error: { code: "RANGE", field: "reps", row: null },
  });
});

test("field order: a reps failure is reported before a unit failure", () => {
  assert.deepEqual(run({ weight: "100", reps: "31", unit: "stone" }), {
    ok: false,
    error: { code: "RANGE", field: "reps", row: null },
  });
  assert.deepEqual(run({ weight: "100", reps: "5", unit: "KG" }), {
    ok: false,
    error: { code: "ENUM", field: "unit", row: null },
  });
});

test("schema failures: null, array, missing, extra, wrong types, accessor", () => {
  const schema = { ok: false, error: { code: "SCHEMA", field: null, row: null } };
  assert.deepEqual(run(null), schema);
  assert.deepEqual(run("100,5,kg"), schema);
  assert.deepEqual(run(["100", "5", "kg"]), schema);
  assert.deepEqual(run({ weight: "100", reps: "5" }), schema);
  assert.deepEqual(run({ weight: "100", reps: "5", unit: "kg", extra: "x" }), schema);
  assert.deepEqual(run({ weight: 100, reps: "5", unit: "kg" }), schema);
  assert.deepEqual(run({ weight: "100", reps: 5, unit: "kg" }), schema);
  assert.deepEqual(run({ weight: "100", reps: "5", unit: null }), schema);
  const withGetter = { weight: "100", unit: "kg" };
  Object.defineProperty(withGetter, "reps", {
    enumerable: true,
    get: () => "5",
  });
  assert.deepEqual(run(withGetter), schema);
});

test("percentage rows: loads are 0.5 multiples based on the rounded headline", () => {
  for (const input of [
    { weight: "77.7", reps: "7", unit: "kg" },
    { weight: "200", reps: "12", unit: "lb" },
    { weight: "33.33", reps: "30", unit: "kg" },
  ]) {
    const outcome = run(input);
    assert.equal(outcome.ok, true);
    const { oneRepMaxKg, rows } = outcome.result;
    assert.equal((oneRepMaxKg * 2) % 1, 0);
    assert.equal(rows.length, 10);
    for (const row of rows) {
      assert.equal((row.loadKg * 2) % 1, 0, `${input.weight} ${row.percent}%`);
    }
  }
});

test("formatKg always shows exactly one decimal", () => {
  assert.equal(formatKg(100.0), "100.0");
  assert.equal(formatKg(97.5), "97.5");
  assert.equal(formatKg(116.7), "116.7");
  assert.equal(formatKg(0.5), "0.5");
  assert.equal(formatKg(0.0), "0.0");
  assert.equal(formatKg(1500.0), "1500.0");
});
